SPARQL:
SELECT ?timeZone ?timeZoneLabel WHERE {
  wd:Q23337 wdt:P421 ?timeZone.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?killer ?killerLabel WHERE {
  wd:Q1048 wdt:P157 ?killer.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel ?elevation WHERE {
  ?item wdt:P31/wdt:P279* ?type;
        wdt:P17 wd:Q183;
        wdt:P2044 ?elevation.
  VALUES ?type { wd:Q8502 wd:Q33515 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?elevation)
LIMIT 1

SELECT DISTINCT ?person ?personLabel WHERE {
  wd:Q8740 wdt:P580 ?warStart; wdt:P582 ?warEnd.
  ?person p:P39 ?statement.
  ?statement ps:P39 wd:Q11696;
             pq:P580 ?start;
             pq:P582 ?end.
  FILTER(?start <= ?warEnd && ?end >= ?warStart)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?state ?stateLabel WHERE {
  ?person rdfs:label "Butch Otter"@en.
  ?person wdt:P39 ?office.
  ?office wdt:P1001 ?state.
  ?state wdt:P31 wd:Q35657.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?artist ?artistLabel WHERE {
  ?rachel rdfs:label "Rachel Stevens"@en;
          wdt:P31 wd:Q5;
          wdt:P106/wdt:P279* wd:Q177220;
          wdt:P569 ?dob.
  ?artist wdt:P31 wd:Q5;
          wdt:P106/wdt:P279* wd:Q483501;
          wdt:P569 ?dob.
  FILTER(?artist != ?rachel)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?occupation ?occupationLabel WHERE {
  VALUES ?article { <https://en.wikipedia.org/wiki/Frank_Herbert> }
  ?article schema:about ?person.
  ?person wdt:P31 wd:Q5;
          wdt:P106 ?occupation.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?capacity WHERE {
  ?club rdfs:label "FC Porto"@en.
  ?club wdt:P115 ?stadium.
  ?stadium wdt:P1083 ?capacity.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?program ?programLabel (COUNT(DISTINCT ?airline) AS ?airlineCount) WHERE {
  ?program wdt:P31 wd:Q586393.
  ?program wdt:P137 ?airline.
  ?airline wdt:P31/wdt:P279* wd:Q46970.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?program ?programLabel
ORDER BY DESC(?airlineCount)
LIMIT 1

SELECT DISTINCT ?country ?countryLabel WHERE {
  ?country wdt:P31 wd:Q3624078;
           wdt:P30 wd:Q46;
           wdt:P122 ?gov.
  ?gov wdt:P279* ?cm.
  ?cm rdfs:label "constitutional monarchy"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?countryLabel

SELECT (COUNT(DISTINCT ?grandchild) AS ?grandchildrenCount) WHERE {
  VALUES ?name { "Jacques-Yves Cousteau"@en "Jacques Cousteau"@en }
  ?person rdfs:label ?name;
          wdt:P31 wd:Q5;
          wdt:P40/wdt:P40 ?grandchild.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?class ?classLabel WHERE {
  ?article schema:about ?millipede;
           schema:isPartOf <https://en.wikipedia.org/>;
           schema:name "Millipede"@en.
  ?millipede wdt:P31 ?class.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?husband ?husbandLabel WHERE {
  ?person rdfs:label "Amanda Palmer"@en.
  ?person wdt:P31 wd:Q5.
  ?person wdt:P26 ?husband.
  ?husband wdt:P21 wd:Q6581097.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?painter ?painterLabel WHERE {
  ?painting wdt:P31 wd:Q3305213;
            (wdt:P1476|rdfs:label) "The Storm on the Sea of Galilee"@en;
            wdt:P170 ?painter.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?start WHERE {
  wd:Q33 p:P463 ?membership.
  ?membership ps:P463 wd:Q458;
              pq:P580 ?start.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?start
LIMIT 1

SELECT DISTINCT ?item ?itemLabel ?award ?awardLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P106 wd:Q82594;
        wdt:P166 ?award.
  ?award wdt:P361 wd:Q19020.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5.
  ?item wdt:P106/wdt:P279* wd:Q36180.
  ?item wdt:P166 wd:Q37922.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?river ?riverLabel ?length WHERE {
  ?river wdt:P31 wd:Q4022;
         (wdt:P17|wdt:P205) wd:Q148;
         wdt:P2043 ?length.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?length)
LIMIT 1

SELECT (COUNT(DISTINCT ?moon) AS ?count) WHERE {
  ?moon wdt:P31 wd:Q2536;
        wdt:P397 wd:Q111.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?realName ?realNameLabel WHERE {
  wd:Q36662 wdt:P9745 ?realName.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?author ?authorLabel WHERE {
  ?item rdfs:label "WikiLeaks"@en.
  ?item wdt:P50 ?author.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?spouse ?spouseLabel WHERE {
  wd:Q91 wdt:P26 ?spouse.
  ?spouse wdt:P21 wd:Q6581072.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?amount ?unitLabel ?pointInTime WHERE {
  wd:Q37156 p:P2139 ?statement.
  ?statement ps:P2139 ?quantity.
  ?quantity wikibase:quantityAmount ?amount ;
            wikibase:quantityUnit ?unit .
  OPTIONAL { ?statement pq:P585 ?pointInTime. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?pointInTime)
LIMIT 1

SELECT ?voice ?voiceLabel WHERE {
  ?character rdfs:label "Bart Simpson"@en.
  ?character wdt:P725 ?voice.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?spouse ?spouseLabel WHERE {
  wd:Q2263 wdt:P26 ?spouse.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P31/wdt:P279* wd:Q40218.
  { ?item wdt:P397 wd:Q111. }
  UNION
  { ?item wdt:P376 wd:Q111. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31/wdt:P279* wd:Q11424;
        wdt:P495 wd:Q213.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P106/wdt:P279* wd:Q11631.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?country ?countryLabel (COUNT(?volcano) AS ?volcanoCount) WHERE {
  ?volcano wdt:P31/wdt:P279* wd:Q8072.
  ?volcano wdt:P17 ?country.
  ?country wdt:P31/wdt:P279* wd:Q6256.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?country ?countryLabel
HAVING (COUNT(?volcano) > 10)
ORDER BY DESC(?volcanoCount)

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P737 wd:Q913.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?lake ?lakeLabel ?maxDepth ?unitLabel WHERE {
  ?lake rdfs:label "Chiemsee"@en;
        wdt:P31/wdt:P279* wd:Q23397.
  ?prop a wikibase:Property;
        rdfs:label "maximum depth"@en;
        wikibase:claim ?p;
        wikibase:statementProperty ?ps;
        wikibase:statementValue ?psv.
  ?lake ?p ?stmt.
  ?stmt wikibase:rank wikibase:PreferredRank.
  ?stmt ?ps ?maxDepth.
  ?stmt ?psv ?vnode.
  ?vnode wikibase:quantityUnit ?unit.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P641 wd:Q8422;
        wdt:P19 ?place.
  ?place wdt:P17 wd:Q928.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q23413;
        wdt:P17 wd:Q30.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT DISTINCT ?country ?countryLabel WHERE {
  wd:Q702 wdt:P17 ?country.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?countryLabel

SELECT ?film ?filmLabel ?releaseDate WHERE {
  SERVICE wikibase:mwapi {
    bd:serviceParam wikibase:endpoint "www.wikidata.org";
    wikibase:api "EntitySearch";
    mwapi:search "Worst Case Scenario";
    mwapi:language "en".
    ?film wikibase:apiOutputItem mwapi:item.
  }
  ?film wdt:P31 wd:Q11424.
  ?film p:P577 ?st.
  ?st ps:P577 ?releaseDate.
  OPTIONAL { ?st pq:P291 ?place. }
  OPTIONAL { ?st pq:P17 ?country. }
  OPTIONAL { ?st pq:P276 ?location. }
  OPTIONAL { ?st pq:P1001 ?jurisdiction. }
  FILTER(
    (?country = wd:Q55) ||
    (?place = wd:Q55) ||
    (?jurisdiction = wd:Q55) ||
    EXISTS { ?place (wdt:P131*|wdt:P17) wd:Q55 } ||
    EXISTS { ?location (wdt:P131*|wdt:P17) wd:Q55 }
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?releaseDate
LIMIT 1

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P1449 ?nick.
  FILTER(LCASE(STR(?nick)) = "scarface")
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?river ?riverLabel WHERE {
  ?river wdt:P31/wdt:P279* wd:Q4022;
         wdt:P403/wdt:P361* ?sea.
  ?sea rdfs:label "North Sea"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?riverLabel

SELECT ?person ?personLabel ?dateOfDeath WHERE {
  VALUES ?person { wd:Q91 }
  ?person wdt:P570 ?dateOfDeath.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
